import{_ as r,o as a,c as l,a0 as t}from"./chunks/framework.DqMqoJl9.js";const m=JSON.parse('{"title":"Rule Sets","description":"","frontmatter":{},"headers":[],"relativePath":"rules.md","filePath":"rules.md"}'),i={name:"rules.md"};function s(o,e,n,c,u,d){return a(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="rule-sets" tabindex="-1">Rule Sets <a class="header-anchor" href="#rule-sets" aria-label="Permalink to &quot;Rule Sets&quot;">​</a></h1><p>All rule sets are rebuilt daily. Download URL pattern:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://github.com/dmulle12/rules/raw/rel/&lt;set&gt;.&lt;format&gt;</span></span></code></pre></div><p>Formats: <code>.list</code> (Surge / Loon), <code>.quanx</code> (Quantumult X), <code>.yaml</code> (Clash), <code>.srs</code> (sing-box).</p><h2 id="reject-—-ad-blocking" tabindex="-1">reject — Ad Blocking <a class="header-anchor" href="#reject-—-ad-blocking" aria-label="Permalink to &quot;reject — Ad Blocking&quot;">​</a></h2><p>Merged upstream ad categories plus manually maintained block rules. Works everywhere.</p><ul><li><a href="https://github.com/dmulle12/rules/raw/rel/reject.list" target="_blank" rel="noreferrer">reject.list</a></li><li><a href="https://github.com/dmulle12/rules/raw/rel/reject.quanx" target="_blank" rel="noreferrer">reject.quanx</a></li><li><a href="https://github.com/dmulle12/rules/raw/rel/reject.yaml" target="_blank" rel="noreferrer">reject.yaml</a></li></ul><h2 id="streaming-cn-—-china-streaming" tabindex="-1">streaming-cn — China Streaming <a class="header-anchor" href="#streaming-cn-—-china-streaming" aria-label="Permalink to &quot;streaming-cn — China Streaming&quot;">​</a></h2><p>NetEase Cloud Music, Bilibili, iQIYI, Youku, Tencent Video, Douyin, Kuaishou, Ximalaya, Kugou, Kuwo. Services that require a mainland China IP — route them via your China policy.</p><ul><li><a href="https://github.com/dmulle12/rules/raw/rel/streaming-cn.list" target="_blank" rel="noreferrer">streaming-cn.list</a></li><li><a href="https://github.com/dmulle12/rules/raw/rel/streaming-cn.quanx" target="_blank" rel="noreferrer">streaming-cn.quanx</a></li><li><a href="https://github.com/dmulle12/rules/raw/rel/streaming-cn.yaml" target="_blank" rel="noreferrer">streaming-cn.yaml</a></li></ul><h2 id="microsoft-—-microsoft-services" tabindex="-1">microsoft — Microsoft Services <a class="header-anchor" href="#microsoft-—-microsoft-services" aria-label="Permalink to &quot;microsoft — Microsoft Services&quot;">​</a></h2><p>Microsoft 365 / Office, Outlook, OneDrive, Xbox, Azure, Bing, plus US school domains. A good fit for US nodes.</p><ul><li><a href="https://github.com/dmulle12/rules/raw/rel/microsoft.list" target="_blank" rel="noreferrer">microsoft.list</a></li><li><a href="https://github.com/dmulle12/rules/raw/rel/microsoft.quanx" target="_blank" rel="noreferrer">microsoft.quanx</a></li><li><a href="https://github.com/dmulle12/rules/raw/rel/microsoft.yaml" target="_blank" rel="noreferrer">microsoft.yaml</a></li></ul><h2 id="gfw-—-gfwlist-users-in-mainland-china" tabindex="-1">gfw — GFWList (users in mainland China) <a class="header-anchor" href="#gfw-—-gfwlist-users-in-mainland-china" aria-label="Permalink to &quot;gfw — GFWList (users in mainland China)&quot;">​</a></h2><p>Domains blocked in mainland China — route via proxy. <strong>Only for users inside mainland China</strong>; not needed elsewhere.</p><ul><li><a href="https://github.com/dmulle12/rules/raw/rel/gfw.list" target="_blank" rel="noreferrer">gfw.list</a></li><li><a href="https://github.com/dmulle12/rules/raw/rel/gfw.quanx" target="_blank" rel="noreferrer">gfw.quanx</a></li><li><a href="https://github.com/dmulle12/rules/raw/rel/gfw.yaml" target="_blank" rel="noreferrer">gfw.yaml</a></li></ul><h2 id="gfw-skip-—-gfw-allowlist" tabindex="-1">gfw-skip — GFW Allowlist <a class="header-anchor" href="#gfw-skip-—-gfw-allowlist" aria-label="Permalink to &quot;gfw-skip — GFW Allowlist&quot;">​</a></h2><p>Allowlist entries from GFWList — direct connection.</p><ul><li><a href="https://github.com/dmulle12/rules/raw/rel/gfw-skip.list" target="_blank" rel="noreferrer">gfw-skip.list</a></li><li><a href="https://github.com/dmulle12/rules/raw/rel/gfw-skip.quanx" target="_blank" rel="noreferrer">gfw-skip.quanx</a></li></ul><h2 id="loc-cn-loc-cn-—-domestic-direct-overseas-proxy" tabindex="-1">loc-cn / loc-!cn — Domestic Direct / Overseas Proxy <a class="header-anchor" href="#loc-cn-loc-cn-—-domestic-direct-overseas-proxy" aria-label="Permalink to &quot;loc-cn / loc-!cn — Domestic Direct / Overseas Proxy&quot;">​</a></h2><ul><li><code>loc-cn</code>: mainland China domains, direct connection.</li><li><code>loc-!cn</code>: non-mainland domains, via proxy. Both are designed for users in mainland China and are usually not needed abroad.</li></ul><h2 id="data-sources" tabindex="-1">Data Sources <a class="header-anchor" href="#data-sources" aria-label="Permalink to &quot;Data Sources&quot;">​</a></h2><p>Rule data comes from <a href="https://github.com/v2fly/domain-list-community" target="_blank" rel="noreferrer">v2fly/domain-list-community</a> and the official <a href="https://github.com/gfwlist/gfwlist" target="_blank" rel="noreferrer">gfwlist/gfwlist</a>, synced and rebuilt daily.</p>',23)])])}const f=r(i,[["render",s]]);export{m as __pageData,f as default};
